        return fail(f"cppcheck: error: unrecognized --showtime mode: '{value}'. Supported modes: file, file-total, summary, top5_file, top5_summary.")
    return None


def read_text_file(path):
    with open(path, 'r', encoding='utf-8', errors='replace') as f:
        return f.read()


def validate_file_exists(path, message_kind):
    if os.path.exists(path):
        return None
    if message_kind == "generic":
        return fail(f"cppcheck: error: couldn't open the file: \\\"{path}\\\".")
    if message_kind == "includes":
        return fail(f"cppcheck: error: unable to open includes file at '{path}'")
    if message_kind == "config_excludes":
        return fail(f"cppcheck: error: unable to open config excludes file at '{path}'")
    raise AssertionError(message_kind)


def validate_suppress_xml(path):
    if not os.path.exists(path):
        return fail(f"cppcheck: error: failed to load suppressions XML '{path}' (XML_ERROR_FILE_NOT_FOUND).")
    try:
        data = open(path, 'rb').read()
    except OSError:
        return fail(f"cppcheck: error: failed to load suppressions XML '{path}' (XML_ERROR_FILE_NOT_FOUND).")
    if len(data) == 0:
        return fail(f"cppcheck: error: failed to load suppressions XML '{path}' (XML_ERROR_EMPTY_DOCUMENT).")
    return None


def parse_file_list(path):
    if not os.path.exists(path):
        return None, fail(f"cppcheck: error: couldn't open the file: \\\"{path}\\\".")
    try:
        content = read_text_file(path)
    except OSError:
        return None, fail(f"cppcheck: error: couldn't open the file: \\\"{path}\\\".")
    count = 0
    for line in content.splitlines():
        if line.strip():
            count += 1
    return count, None


def parse_project(path):
    if not os.path.exists(path):
        return None, fail(f"cppcheck: error: failed to open project '{path}'. The file does not exist.")
    lower = path.lower()
    if lower.endswith('.json'):
        try:
            data = json.loads(read_text_file(path))
        except Exception:
            write("cppcheck: error: compilation database is not a JSON array\\n")
            return None, fail(f"cppcheck: error: failed to load project '{path}'. An error occurred.")
        if not isinstance(data, list):
            write("cppcheck: error: compilation database is not a JSON array\\n")
            return None, fail(f"cppcheck: error: failed to load project '{path}'. An error occurred.")
        for entry in data:
            if not isinstance(entry, dict) or 'directory' not in entry:
                write("cppcheck: error: 'directory' field in compilation database entry missing\\n")
                return None, fail(f"cppcheck: error: failed to load project '{path}'. An error occurred.")
        return len(data), None
    try:
        content = read_text_file(path)
    except OSError:
        return None, fail(f"cppcheck: error: failed to open project '{path}'. The file does not exist.")
    # The observed .cppcheck file with an empty <project> had no sources. A project
    # mentioning common source suffixes behaves as a non-empty project before the
    # missing std.cfg failure.
    source_re = re.compile(r"\\.(?:c|cc|cpp|cxx|c\\+\\+|ipp|ixx|tpp|txx)\\b", re.IGNORECASE)
    return (1 if source_re.search(content) else 0), None


